module dma_controller(  
    input clk,  
    input reset,  
    input [7:0] enable,  
    input [7:0] start,  
    output reg [7:0] transfer_complete  
);  
    reg [7:0] active_channel;  
    reg [7:0] transfer_state;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            active_channel <= 8'b0;  
            transfer_complete <= 8'b0;  
            transfer_state <= 8'b0;  
        end else begin  
            active_channel <= enable & start;  
            transfer_state <= active_channel;  
            transfer_complete <= transfer_state;  
            // Simulate transfer completion  
            transfer_complete <= transfer_state;  
        end  
    end  
endmodule

