module pitch_detector(  
    input clk,  
    input rst,  
    input [9:0] sample,  
    output reg detected  
);  
    parameter TARGET_PITCH = 10'b1010101010; // example target pitch pattern  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            detected <= 1'b0;  
        end else begin  
            if (sample == TARGET_PITCH)  
                detected <= 1'b1;  
            else  
                detected <= 1'b0;  
        end  
    end  
endmodule

