module pulse_generator(  
    input clk,  
    input trigger,  
    input [7:0] width,  
    output reg pulse  
);  
    reg [7:0] count;  
    reg pulse_active;  

    always @(posedge clk) begin  
        if (trigger) begin  
            pulse_active <= 1'b1;  
            count <= width;  
        end  
        if (pulse_active) begin  
            if (count > 0) begin  
                count <= count - 1;  
                pulse <= 1'b1;  
            end else begin  
                pulse <= 1'b0;  
                pulse_active <= 1'b0;  
            end  
        end else begin  
            pulse <= 1'b0;  
        end  
    end  
endmodule

