module carrier_recovery (
    input wire clk,
    input wire data_in,
    output reg clk_out
);
    reg [1:0] state;

    always @(posedge clk) begin
        case (state)
            2'b00: begin
                clk_out <= 0;
                if (data_in == 1)
                    state <= 2'b01;
            end
            2'b01: begin
                clk_out <= 1;
                if (data_in == 0)
                    state <= 2'b10;
            end
            2'b10: begin
                clk_out <= 0;
                if (data_in == 1)
                    state <= 2'b01;
            end
            default: begin
                state <= 2'b00;
            end
        endcase
    end
endmodule

