module pulse_generator (
    input clk,
    input rst,
    output reg pulse
);
    reg [3:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            pulse <= 0;
        end else begin
            if (count < 10) count <= count + 1;
            else count <= 0;

            if (count < 5) pulse <= 1;
            else pulse <= 0;
        end
    end
endmodule

