module rsa_encrypt (
    input clk,
    input rst,
    input [15:0] plaintext,
    input [15:0] exponent,
    input [15:0] modulus,
    output reg [15:0] ciphertext
);
    reg [15:0] result;
    reg [15:0] base;
    reg [15:0] exp;
    reg [15:0] mod;
    reg [3:0] state;

    parameter IDLE = 4'b0000,
              LOAD = 4'b0001,
              CALCULATE = 4'b0010,
              OUTPUT = 4'b0011;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            result <= 16'b1;
            base <= 16'b0;
            exp <= 16'b0;
            mod <= 16'b0;
            ciphertext <= 16'b0;
        end else begin
            case (state)
                IDLE: begin
                    state <= LOAD;
                end
                LOAD: begin
                    base <= plaintext;
                    exp <= exponent;
                    mod <= modulus;
                    state <= CALCULATE;
                end
                CALCULATE: begin
                    if (exp > 0) begin
                        if (exp[0] == 1) begin
                            result <= (result * base) % mod;
                        end
                        base <= (base * base) % mod;
                        exp <= exp >> 1;
                    end else begin
                        state <= OUTPUT;
                    end
                end
                OUTPUT: begin
                    ciphertext <= result;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

