module spi_controller(  
    input wire clk,  
    input wire rst,  
    input wire cs,  
    input wire mosi,  
    output reg miso,  
    output reg [7:0] data_out,  
    output reg data_ready  
);  
    reg [7:0] data_in;  
    reg [2:0] bit_count;  
    reg receiving;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            data_out <= 8'b0;  
            miso <= 1'b0;  
            data_ready <= 1'b0;  
            bit_count <= 3'b0;  
            receiving <= 1'b0;  
        end else if (cs) begin  
            if (receiving) begin  
                data_in <= {data_in[6:0], mosi};  
                bit_count <= bit_count + 1;  
                if (bit_count == 3'b111) begin  
                    data_out <= data_in;  
                    data_ready <= 1'b1;  
                    receiving <= 1'b0;  
                    bit_count <= 3'b0;  
                end  
            end  
        end else begin  
            receiving <= 1'b1;  
            bit_count <= 3'b0;  
            data_ready <= 1'b0;  
        end  
        miso <= data_out[7];  
        data_out <= {data_out[6:0], 1'b0};  
    end  
endmodule

