module noise_suppression(
    input wire clk,
    input wire reset,
    input wire signal_in,
    output reg signal_out
);
    parameter STABLE_CYCLES = 4;
    reg [1:0] state; // 0 - unstable, 1 - stable
    reg [2:0] count; // count stable cycles
    reg last_signal;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 0;
            count <= 0;
            signal_out <= 0;
            last_signal <= 0;
        end else begin
            if (signal_in == last_signal) begin
                if (count < STABLE_CYCLES - 1) begin
                    count <= count + 1;
                end else begin
                    signal_out <= signal_in;
                end
                state <= 1; // stable
            end else begin
                count <= 0;
                state <= 0; // unstable
            end
            last_signal <= signal_in;
        end
    end
endmodule

