module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    output reg timeout  
);  
    reg [3:0] counter; // 4-bit counter to track time  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 4'b0000;  
            timeout <= 1'b0;  
        end else begin  
            if (counter < 4'd10) begin  
                counter <= counter + 1;  
                timeout <= 1'b0;  
            end else begin  
                timeout <= 1'b1;  
            end  
        end  
    end  
endmodule

