        // Simple logic: allocate weights based on returns
        if (asset1_return >= asset2_return && asset1_return >= asset3_return) begin
            weight1 = 8'd100;
            weight2 = 8'd0;
            weight3 = 8'd0;
        end else if (asset2_return >= asset1_return && asset2_return >= asset3_return) begin
            weight1 = 8'd0;
            weight2 = 8'd100;
            weight3 = 8'd0;
        end else begin
            weight1 = 8'd0;
            weight2 = 8'd0;
            weight3 = 8'd100;
        end
    end
endmodule

