module uart_transmitter (
    input wire [7:0] data_in,
    input wire start,
    output reg tx,
    output reg busy,
    input wire clk
);
    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000; // Example: 50 MHz clock
    parameter BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] state;
    reg [3:0] bit_index;
    reg [15:0] clk_div;

    localparam IDLE = 0;
    localparam START_BIT = 1;
    localparam DATA_BITS = 2;
    localparam STOP_BIT = 3;

    initial begin
        tx = 1; // Idle state is high
        busy = 0;
        state = IDLE;
        clk_div = 0;
        bit_index = 0;
    end

    always @(posedge clk) begin
        if (state == IDLE) begin
            if (start) begin
                busy <= 1;
                state <= START_BIT;
                clk_div <= 0;
                bit_index <= 0;
            end
        end else if (state == START_BIT) begin
            if (clk_div < BIT_PERIOD - 1) begin
                clk_div <= clk_div + 1;
            end else begin
                clk_div <= 0;
                tx <= 0; // Send start bit
                state <= DATA_BITS;
            end
        end else if (state == DATA_BITS) begin
            if (clk_div < BIT_PERIOD - 1) begin
                clk_div <= clk_div + 1;
            end else begin
                clk_div <= 0;
                tx <= data_in[bit_index]; // Send data bit
                bit_index <= bit_index + 1;
                if (bit_index == 7) begin
                    state <= STOP_BIT;
                end
            end
        end else if (state == STOP_BIT) begin
            if (clk_div < BIT_PERIOD - 1) begin
                clk_div <= clk_div + 1;
            end else begin
                clk_div <= 0;
                tx <= 1; // Send stop bit
                busy <= 0; // Transmission is complete
                state <= IDLE;
            end
        end
    end
endmodule

