module dma_controller (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [1:0] channel_sel,
    input wire [3:0] channel_enable,
    output reg transfer_complete
);

    reg [1:0] current_channel;
    reg transferring;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_channel <= 2'b00;
            transferring <= 1'b0;
            transfer_complete <= 1'b0;
        end else begin
            if (start && channel_enable[channel_sel]) begin
                transferring <= 1'b1;
                current_channel <= channel_sel;
                transfer_complete <= 1'b0;
            end

            if (transferring) begin
                // Simulate data transfer logic
                // After some cycles, we consider the transfer complete
                transfer_complete <= 1'b1;
                transferring <= 1'b0;
            end
        end
    end
endmodule

