module fir_filter (
    input wire clk,
    input wire rst,
    input wire [15:0] x_in,
    output reg [15:0] y_out
);
    reg [15:0] coeffs [0:31]; // Coefficients
    reg [15:0] x_history [0:31]; // Input history
    integer i;

    initial begin
        // Initialize coefficients (example values)
        coeffs[0] = 16'd1; coeffs[1] = 16'd1; coeffs[2] = 16'd1; coeffs[3] = 16'd1;
        coeffs[4] = 16'd1; coeffs[5] = 16'd1; coeffs[6] = 16'd1; coeffs[7] = 16'd1;
        coeffs[8] = 16'd1; coeffs[9] = 16'd1; coeffs[10] = 16'd1; coeffs[11] = 16'd1;
        coeffs[12] = 16'd1; coeffs[13] = 16'd1; coeffs[14] = 16'd1; coeffs[15] = 16'd1;
        coeffs[16] = 16'd1; coeffs[17] = 16'd1; coeffs[18] = 16'd1; coeffs[19] = 16'd1;
        coeffs[20] = 16'd1; coeffs[21] = 16'd1; coeffs[22] = 16'd1; coeffs[23] = 16'd1;
        coeffs[24] = 16'd1; coeffs[25] = 16'd1; coeffs[26] = 16'd1; coeffs[27] = 16'd1;
        coeffs[28] = 16'd1; coeffs[29] = 16'd1; coeffs[30] = 16'd1; coeffs[31] = 16'd1;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y_out <= 16'd0;
            for (i = 0; i < 32; i = i + 1) begin
                x_history[i] <= 16'd0;
            end
        end else begin
            // Shift history
            for (i = 31; i > 0; i = i - 1) begin
                x_history[i] <= x_history[i - 1];
            end
            x_history[0] <= x_in;

            // Calculate y_out
            y_out <= 16'd0;
            for (i = 0; i < 32; i = i + 1) begin
                y_out <= y_out + (x_history[i] * coeffs[i]);
            end
        end
    end
endmodule

