module float_adder(  
    input [31:0] a,  
    input [31:0] b,  
    output reg [31:0] sum  
);  
    wire sign_a, sign_b;  
    wire [7:0] exp_a, exp_b;  
    wire [22:0] frac_a, frac_b;  
    wire [7:0] exp_diff;  
    wire [23:0] aligned_frac_a, aligned_frac_b;  
    wire [23:0] frac_sum;  
    wire sign_sum;  
    wire [7:0] exp_sum;  

    assign sign_a = a[31];  
    assign exp_a = a[30:23];  
    assign frac_a = {1'b1, a[22:0]};  
    assign sign_b = b[31];  
    assign exp_b = b[30:23];  
    assign frac_b = {1'b1, b[22:0]};  

    assign exp_diff = exp_a - exp_b;  
    assign aligned_frac_a = (exp_diff > 0) ? frac_a : (frac_a >> (-exp_diff));  
    assign aligned_frac_b = (exp_diff > 0) ? (frac_b >> exp_diff) : frac_b;  

    assign {sign_sum, frac_sum} = aligned_frac_a + aligned_frac_b;  
    assign exp_sum = (exp_a > exp_b ? exp_a : exp_b) + (frac_sum[23] ? 1 : 0);  

    always @(*) begin  
        sum = {sign_sum, exp_sum, frac_sum[22:0]};  
    end  
endmodule

module pipeline_processor(
    input clk,
    input rst,
    input [31:0] instruction,
    output reg [31:0] result
);
    reg [31:0] IF_ID_instruction;
    reg [31:0] ID_EX_instruction;
    reg [31:0] EX_MEM_instruction;
    reg [31:0] MEM_WB_instruction;

    // Register file (simplified)
    reg [31:0] reg_file[0:31];
    reg [31:0] alu_result;

    // Pipeline stages
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            IF_ID_instruction <= 32'b0;
            ID_EX_instruction <= 32'b0;
            EX_MEM_instruction <= 32'b0;
            MEM_WB_instruction <= 32'b0;
            result <= 32'b0;
        end else begin
            // Stage 1: Instruction Fetch
            IF_ID_instruction <= instruction;

            // Stage 2: Instruction Decode
            ID_EX_instruction <= IF_ID_instruction;

            // Stage 3: Execute
            alu_result <= reg_file[ID_EX_instruction[25:21]] + reg_file[ID_EX_instruction[20:16]];
            EX_MEM_instruction <= {alu_result, ID_EX_instruction[15:0]}; // Store result for MEM stage

            // Stage 4: Memory Access
            MEM_WB_instruction <= EX_MEM_instruction;

            // Stage 5: Write Back
            result <= MEM_WB_instruction[31:0]; // Write result back to register
        end
    end
endmodule

