module kalman_filter (  
    input clk,  
    input reset,  
    input [15:0] z, // measurement input  
    output reg [15:0] x_hat, // estimated position  
    output reg [15:0] p_hat // estimated error covariance  
);  

    reg [15:0] p; // process noise covariance  
    reg [15:0] k; // kalman gain  

    initial begin  
        x_hat = 16'h0000;  
        p_hat = 16'hFFFF; // large initial uncertainty  
        p = 16'h0001; // process noise  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            x_hat <= 16'h0000;  
            p_hat <= 16'hFFFF;  
        end else begin  
            // Prediction step  
            p_hat <= p_hat + p;  

            // Update step  
            k <= p_hat / (p_hat + 16'h0001); // measurement noise is assumed to be 1  
            x_hat <= x_hat + k * (z - x_hat);  
            p_hat <= (16'hFFFF - k) * p_hat;  
        end  
    end  
endmodule

module T_latch(  
    input wire T,  
    input wire clk,  
    output reg Q  
);  
    always @(posedge clk) begin  
        if (T)  
            Q <= ~Q;  
    end  
endmodule

