module floyd_warshall(clk, rst, start, adj_matrix, done, shortest_path);
    input clk;
    input rst;
    input start;
    input [63:0] adj_matrix; // 4x4 adjacency matrix for 4 nodes
    output reg done;
    output reg [63:0] shortest_path; // 4x4 shortest path matrix

    reg [2:0] k, i, j; // Iterators for the algorithm
    reg [63:0] matrix [0:3][0:3]; // 2D matrix for storing shortest paths

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            done <= 0;
            shortest_path <= 64'd0;
            k <= 0;
            i <= 0;
            j <= 0;
            // Initialize the matrix with the input adjacency matrix
            for (i = 0; i < 4; i = i + 1) begin
                for (j = 0; j < 4; j = j + 1) begin
                    matrix[i][j] <= (adj_matrix[i * 16 + j * 4 +: 4] == 4'b1111) ? 16'hFFFF : adj_matrix[i * 16 + j * 4 +: 4]; 
                end
            end
        end else if (start) begin
            if (k < 4) begin
                for (i = 0; i < 4; i = i + 1) begin
                    for (j = 0; j < 4; j = j + 1) begin
                        if (matrix[i][j] > (matrix[i][k] + matrix[k][j])) begin
                            matrix[i][j] <= (matrix[i][k] + matrix[k][j]);
                        end
                    end
                end
                k <= k + 1;
            end else begin
                // Transfer final results to shortest_path output
                for (i = 0; i < 4; i = i + 1) begin
                    for (j = 0; j < 4; j = j + 1) begin
                        shortest_path[i * 16 + j * 4 +: 4] <= matrix[i][j];
                    end
                end
                done <= 1;
            end
        end
    end
endmodule

