module tcp_segmentation #(parameter DATA_WIDTH = 64, SEGMENT_WIDTH = 16) (  
    input wire clk,  
    input wire reset,  
    input wire [DATA_WIDTH-1:0] data_in,  
    input wire valid_in,  
    output reg [SEGMENT_WIDTH-1:0] segment_out,  
    output reg valid_out,  
    output reg done  
);  
    reg [5:0] segment_count;  
    reg [DATA_WIDTH-1:0] data_buffer;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            segment_count <= 0;  
            valid_out <= 0;  
            done <= 0;  
            data_buffer <= 0;  
        end else if (valid_in) begin  
            data_buffer <= data_in;  
            segment_count <= 0;  
            valid_out <= 1;  
            done <= 0;  
        end else if (valid_out) begin  
            if (segment_count < (DATA_WIDTH / SEGMENT_WIDTH)) begin  
                segment_out <= data_buffer[segment_count*SEGMENT_WIDTH +: SEGMENT_WIDTH];  
                segment_count <= segment_count + 1;  
            end else begin  
                valid_out <= 0;  
                done <= 1;  
            end  
        end  
    end  
endmodule

