module bellman_ford #(parameter V = 5, E = 10, INF = 16'hFFFF) (  
    input clk,  
    input reset,  
    input [V-1:0] src,  
    input [E*2-1:0] edges, // Edge list: each pair of [from, to, weight]  
    input [E*16-1:0] weights,  
    output reg [V*16-1:0] dist  
);  
    integer i, j;  
    reg [15:0] distance [0:V-1];  
    reg [15:0] edge_weight [0:E-1];  
    reg [V-1:0] edge_from [0:E-1];  
    reg [V-1:0] edge_to [0:E-1];  
    reg [3:0] iteration;  

    initial begin  
        for (i = 0; i < V; i = i + 1) begin  
            distance[i] = INF;  
        end  
        dist = {V{INF}};  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            for (i = 0; i < V; i = i + 1) begin  
                distance[i] = INF;  
            end  
            distance[src] = 0;  
            iteration = 0;  
        end else if (iteration < V-1) begin  
            for (i = 0; i < E; i = i + 1) begin  
                edge_from[i] = edges[i*2 +: V];  
                edge_to[i] = edges[i*2 + V +: V];  
                edge_weight[i] = weights[i*16 +: 16];  
            end  
            for (i = 0; i < E; i = i + 1) begin  
                if (distance[edge_from[i]] + edge_weight[i] < distance[edge_to[i]]) begin  
                    distance[edge_to[i]] = distance[edge_from[i]] + edge_weight[i];  
                end  
            end  
            iteration = iteration + 1;  
        end else begin  
            for (i = 0; i < V; i = i + 1) begin  
                dist[i*16 +: 16] = distance[i];  
            end  
        end  
    end  
endmodule

module audio_sample_buffer (
    input clk,
    input reset,
    input write_enable,
    input [15:0] data_in,
    output reg [15:0] data_out,
    output reg valid
);
    reg [15:0] buffer [0:7]; // FIFO buffer of 8 samples
    reg [2:0] head; // Points to the current write location
    reg [2:0] tail; // Points to the current read location
    reg [3:0] count; // Number of samples currently in the buffer

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            head <= 3'b000;
            tail <= 3'b000;
            count <= 4'b0000;
            valid <= 1'b0;
        end else begin
            if (write_enable) begin
                buffer[head] <= data_in;
                head <= (head + 1) % 8;
                if (count < 8) begin
                    count <= count + 1;
                end
                if (count == 7) begin
                    tail <= (tail + 1) % 8; // Move tail when full
                end
            end

            // Output logic
            if (count > 0) begin
                data_out <= buffer[tail];
                valid <= 1'b1;
            end else begin
                valid <= 1'b0;
            end
        end
    end
endmodule

