module BellmanFord #(parameter N = 5) (  
    input [N*N-1:0] adj_matrix, // adjacency matrix flattened  
    input [N-1:0] weights, // weights of edges  
    input [2:0] source, // source vertex  
    output reg [N-1:0] distances // shortest distances to each vertex  
);  
    integer i, j, k;  
    reg [N-1:0] temp_distances;  

    initial begin  
        // Initialize distances  
        for (i = 0; i < N; i = i + 1)  
            distances[i] = (i == source) ? 0 : 8'hFF; // 8'hFF represents infinity  
    end  

    always @* begin  
        temp_distances = distances;  
        for (k = 0; k < N-1; k = k + 1) begin  
            for (i = 0; i < N; i = i + 1) begin  
                for (j = 0; j < N; j = j + 1) begin  
                    if (adj_matrix[i*N+j] && (temp_distances[i] + weights[j] < distances[j])) begin  
                        distances[j] = temp_distances[i] + weights[j];  
                    end  
                end  
            end  
        end  
    end  
endmodule

